            apClone.updateAlways = true;

            ModManager.Instance.ShowModStamp();
        }
        catch (Exception ex)
        {
            LightLogger.LogWarning("[Light] VersionPatch.Postfix NRE: " + ex.Message + "\n" + ex.StackTrace);
        }
    }
