        {
            try
            {
                if (string.IsNullOrEmpty(KickManager.kickReason))
                    return true;
                float now = Time.realtimeSinceStartup;
                if (KickManager.kickReasonConsumeUntil > 0f)
                {
                    if (now > KickManager.kickReasonConsumeUntil)
                    {
                        KickManager.Clear();
                        return true;
